import{_ as n,o as i,c as a,ag as r}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"nay_lib","description":"","frontmatter":{},"headers":[],"relativePath":"de/nay-lib/index.md","filePath":"de/nay-lib/index.md"}'),t={name:"de/nay-lib/index.md"};function s(o,e,d,l,h,c){return i(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="nay-lib" tabindex="-1">nay_lib <a class="header-anchor" href="#nay-lib" aria-label="Permalink to &quot;nay_lib&quot;">​</a></h1><p><code>nay_lib</code> ist die gemeinsame Bibliothek hinter jedem Nayretis Skript. Du bekommst sie mit jedem Kauf, installierst sie einmal, und jedes Nayretis Skript, das du hinzufügst, nutzt sie.</p><h2 id="was-sie-dir-bietet" tabindex="-1">Was sie dir bietet <a class="header-anchor" href="#was-sie-dir-bietet" aria-label="Permalink to &quot;Was sie dir bietet&quot;">​</a></h2><ul><li><strong>Ein Einstellungspanel</strong>, <code>/nay</code>, für jedes Nayretis Skript. Einstellungen werden in deiner Datenbank gespeichert und beim Speichern sofort für jeden Spieler übernommen. Siehe <a href="/de/nay-lib/panel">/nay Panel</a>.</li><li><strong>Berechtigungen</strong> per ACE oder per Discord-, Steam-, FiveM- oder License-Kennung. Siehe <a href="/de/nay-lib/permissions">Berechtigungen</a>.</li><li><strong>Sechs Sprachen</strong>: Englisch, Französisch, Spanisch, Portugiesisch, Polnisch und Deutsch. Fehlt eine Übersetzung, wird Englisch angezeigt.</li><li><strong>Framework-Bridge</strong>: ESX Legacy, QBCore, QBox und ox_core werden automatisch erkannt, mit ihren Inventaren, Targets und Benachrichtigungen. Siehe <a href="/de/bridge/">Bridge</a>.</li><li><strong>HTTP-API</strong> für deine Website, dein Dashboard oder deinen Discord-Bot, standardmäßig aus. Siehe <a href="/de/nay-lib/api">HTTP-API</a>.</li><li><strong>Webhooks</strong>, auch als Discord-Nachrichten, für Ereignisse der Skripte. Siehe <a href="/de/nay-lib/webhooks">Webhooks</a>.</li><li><strong>Protokoll</strong> jeder Änderung, ob im Spiel, über die Konsole oder über die API. Siehe <a href="/de/nay-lib/audit">Protokoll</a>.</li><li>Nayretis Benachrichtigungen, Texthinweise und Fortschrittsbalken, von allen Skripten gemeinsam genutzt.</li></ul><h2 id="voraussetzungen-und-startreihenfolge" tabindex="-1">Voraussetzungen und Startreihenfolge <a class="header-anchor" href="#voraussetzungen-und-startreihenfolge" aria-label="Permalink to &quot;Voraussetzungen und Startreihenfolge&quot;">​</a></h2><p>Die einzige Abhängigkeit ist <a href="https://github.com/overextended/oxmysql" target="_blank" rel="noreferrer">oxmysql</a>. Starte <code>nay_lib</code> nach deinen Framework-, Inventar- und Target-Ressourcen und vor jedem Nayretis Skript:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span></code></pre></div><p>Die Tabellen werden beim ersten Start angelegt. Serveroptionen, die in der <code>server.cfg</code> stehen, findest du auf der Seite <a href="/de/nay-lib/convars">Convars</a>.</p>`,8)])])}const p=n(t,[["render",s]]);export{u as __pageData,p as default};
